import React, { useState } from "react";
import styled from "styled-components";
import SVgs from "../components/ImageZoom";
import LogMIC from "../components/LogMIC";

const Container = styled.div`
  text-align: center;
  font-family: Arial, sans-serif;
`;

const Button = styled.button`
  padding: 10px 20px;
  margin: 10px;
  font-size: 16px;
  background-color: ${(props) => (props.active ? "#4caf50" : "#d3d3d3")};
  color: ${(props) => (props.active ? "white" : "#666")};
  border: none;
  border-radius: 5px;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    background-color: ${(props) => (props.active ? "#45a049" : "#a9a9a9")};
  }
`;

const ChartTitle = styled.h3`
  font-size: 20px;
  color: #333;
`;

const StatisticsView = () => {
  const [activeChart, setActiveChart] = useState(null);

  const toggleChart = (name) => {
    setActiveChart((prev) => (prev === name ? null : name));
  };

  return (
    <Container>
      <h1>Statistics Viewer</h1>
      <div>
        <Button
          active={activeChart === "histogram"}
          onClick={() => toggleChart("histogram")}
        >
          Histogram
        </Button>
        <Button
          active={activeChart === "amrplot"}
          onClick={() => toggleChart("amrplot")}
        >
          AMR Plot
        </Button>
        <Button
          active={activeChart === "vfactorsplot"}
          onClick={() => toggleChart("vfactorsplot")}
        >
          VFactors Plot
        </Button>
      </div>

      {activeChart === "histogram" && (
        <>
          <ChartTitle>Histogram</ChartTitle>
          <LogMIC />
        </>
      )}
      {activeChart === "amrplot" && (
        <>
          <ChartTitle>AMR Plot</ChartTitle>
          <SVgs file_dist="amr.json" />
        </>
      )}
      {activeChart === "vfactorsplot" && (
        <>
          <ChartTitle>VFactors Plot</ChartTitle>
          <SVgs file_dist="vfactor.json" />
        </>
      )}
    </Container>
  );
};

export default StatisticsView;
